/// Given a non-empty slice `a` of integers and two indices `s` and `e`
/// defining a half-open subarray [s, e), returns the index of a minimum
/// element within that subarray.
///
/// Precondition: 0 <= s < e <= a.len().
#[requires(s < e && e <= a.len())]
#[ensures(s <= result && result < e)]
#[ensures(forall(|k: usize| s <= k && k < e ==> a[result] <= a[k]))]
pub fn find_min_index(a: &[i32], s: usize, e: usize) -> usize {
    // still keep the debug‐assert for Rust‐side checking
    debug_assert!(s < e && e <= a.len(), "Invalid subarray bounds");

    let mut min_i = s;

    // We iterate i from s+1 up to e-1.  The invariant states:
    //  1) min_i is always in [s, i)
    //  2) a[min_i] is ≤ every element in a[s..i)
    // The decreases clause shows that e - i strictly decreases each iteration.
    #[invariant(s <= min_i && min_i < i)]
    #[invariant(forall(|k: usize| s <= k && k < i ==> a[min_i] <= a[k]))]
    #[decreases(e - i)]
    for i in (s + 1)..e {
        if a[i] < a[min_i] {
            min_i = i;
        }
    }

    min_i
}

